 async function archiveAccount(account:Account){const transactionCount=transactions.filter(tx=>tx.account_id===account.id).length,statementCount=statements.filter(statement=>statement.account_id===account.id).length;if(!window.confirm(`归档账户？\n\n${account.name}\n\n此账户关联：\n- ${transactionCount} 笔交易\n- ${statementCount} 份银行流水\n\n归档后历史数据与统计会保留，但不能再上传新流水。`))return;setBusy(true);const{error}=await supabase().from("accounts").update({is_archived:true,updated_at:new Date().toISOString()}).eq("id",account.id);setBusy(false);if(error)setNotice({tone:"error",text:`账户归档失败：${error.message}`});else{setAccounts(rows=>rows.map(row=>row.id===account.id?{...row,is_archived:true}:row));if(uploadAccount===account.id)setUploadAccount("");if(analysisAccount===account.id)setAnalysisAccount("all");setEditingAccount(null);setNotice({tone:"success",text:"账户已安全归档，历史交易与账单均已保留。"})}}
