 async function saveManualRate(transaction:Tx,value:string){if(!user)return false;const fields=manualFxFields(Number(transaction.original_amount??transaction.amount),settings.base_currency,value);if(!fields){setNotice({tone:"error",text:"请输入大于 0 的有效汇率。"});return false}setBusy(true);const next={...fields,exchange_rate_updated_by:user.id};const{error}=await supabase().from("transactions").update(next).eq("id",transaction.id);setBusy(false);if(error){setNotice({tone:"error",text:`汇率保存失败：${error.message}`});return false}const updated={...transaction,...next};setTransactions(rows=>rows.map(row=>row.id===transaction.id?updated:row));setEditingTransaction(updated);setNotice({tone:"success",text:"手动汇率已保存，Dashboard 已按新折算金额更新。"});return true}
