 async function createTag(name:string){if(!user||!name.trim())return;const{data,error}=await supabase().from("tags").insert({user_id:user.id,name:name.trim()}).select("id,name").single();if(error)setNotice({tone:"error",text:`标签创建失败：${error.message}`});else setTags(v=>[...v,data as Tag].sort((a,b)=>a.name.localeCompare(b.name,"zh-CN")))}
 async function renameTag(tag:Tag,name:string){if(!name.trim()||name.trim()===tag.name)return;const{error}=await supabase().from("tags").update({name:name.trim(),updated_at:new Date().toISOString()}).eq("id",tag.id);if(error)setNotice({tone:"error",text:`标签重命名失败：${error.message}`});else setTags(v=>v.map(item=>item.id===tag.id?{...item,name:name.trim()}:item))}
 async function deleteTag(tag:Tag){if(!window.confirm(`删除标签“${tag.name}”？交易不会被删除。`))return;const{error}=await supabase().from("tags").delete().eq("id",tag.id);if(error)setNotice({tone:"error",text:`标签删除失败：${error.message}`});else{setTags(v=>v.filter(item=>item.id!==tag.id));setTransactionTags(v=>v.filter(link=>link.tag_id!==tag.id));if(tagFilter===tag.id)setTagFilter("all")}}
 async function saveBudget(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!editingBudget)return;const amount=Number(new FormData(e.currentTarget).get("amount"));if(amount<=0)return;setBusy(true);const{error}=await supabase().from("budgets").update({amount,updated_at:new Date().toISOString()}).eq("id",editingBudget.id);setBusy(false);if(error)setNotice({tone:"error",text:`预算更新失败：${error.message}`});else{setBudgets(v=>v.map(x=>x.id===editingBudget.id?{...x,amount}:x));setEditingBudget(null)}}
 async function saveSettings(currency:string){if(!user||currency===settings.base_currency){setShowSettings(false);return}if(!window.confirm(`将本位币改为 ${currency}？现有跨币种交易需要重新确认汇率。`))return;setBusy(true);const c=supabase();try{const saved=await c.from("user_settings").upsert({user_id:user.id,base_currency:currency,updated_at:new Date().toISOString()});if(saved.error)throw saved.error;const reset=await c.from("transactions").update({base_currency:currency,base_amount:null,exchange_rate:null,exchange_rate_date:null,exchange_rate_source:null,conversion_status:"pending"}).neq("id","00000000-0000-0000-0000-000000000000");if(reset.error)throw reset.error;const same=await c.from("transactions").update({base_currency:currency,exchange_rate:1,exchange_rate_source:"base_currency",conversion_status:"converted"}).eq("original_currency",currency);if(same.error)throw same.error;const recalc=await c.from("transactions").select("id,original_amount,transaction_date").eq("original_currency",currency);if(recalc.error)throw recalc.error;for(const row of recalc.data??[]){await c.from("transactions").update({base_amount:Number(row.original_amount),exchange_rate_date:row.transaction_date}).eq("id",row.id)}setSettings({base_currency:currency});setShowSettings(false);await loadData(user.id);setNotice({tone:"success",text:`本位币已改为 ${currency}；其他币种交易已标记为汇率待确认。`})}catch(error){setNotice({tone:"error",text:`本位币更新失败：${errorText(error)}`})}finally{setBusy(false)}}
 async function addBudgetCategory(categoryKey:string){if(!user||!categoryKey)return;const definition=expenseCategories.find(category=>category.key===categoryKey);if(!definition)return;setBusy(true);const suggested=defaultBudgets.find(item=>item.category===categoryKey);const{data,error}=await supabase().from("budgets").insert({user_id:user.id,month:`${budgetMonth}-01`,category:categoryKey,amount:suggested?.amount??1500,color:definition.color}).select("id,month,category,amount,color").single();setBusy(false);if(error)setNotice({tone:"error",text:`添加预算分类失败：${error.message}`});else setBudgets(rows=>[data as Budget,...rows])}
