function KpiDrilldown({kind,transactions,accounts,categories,baseCurrency,onEdit,onClose}:{kind:"income"|"expense";transactions:Tx[];accounts:Account[];categories:Category[];baseCurrency:string;onEdit:(tx:Tx)=>void;onClose:()=>void}){const title=kind==="income"?"本期收入":"本期普通消费",total=transactions.reduce((sum,tx)=>sum+(amountInBase(tx)??0),0),accountMap=new Map(accounts.map(account=>[account.id,account.name])),categoryMap=new Map(categories.map(category=>[category.id,category.name]));return <div className="drawer-backdrop" onClick={onClose}><aside className="detail-drawer" onClick={event=>event.stopPropagation()}><div className="drawer-head"><div><span className="section-kicker">KPI 交易明细</span><h2>{title}</h2><strong>{money(total,baseCurrency)}</strong><p>共 {transactions.length} 笔交易</p></div><button className="icon-button" onClick={onClose} aria-label="关闭">×</button></div>{transactions.length?<div className="drawer-list">{transactions.map(tx=><button className="drawer-transaction" key={tx.id} onClick={()=>onEdit(tx)}><time>{tx.transaction_date}</time><div><b>{displayDescription(tx)}{tx.note&&<em className="note-indicator" title="有备注">📝</em>}</b><span>{categoryMap.get(tx.category_id??"")??transactionTypeLabels[tx.transaction_type??"review"]} · {accountMap.get(tx.account_id)??"历史账户"}</span></div><strong className={kind==="income"?"plus":"minus"}>{kind==="income"?"+":"−"}{money(Number(tx.amount),tx.raw_data?.currency)}</strong></button>)}</div>:<div className="empty">当前范围内没有符合统计口径的交易。</div>}</aside></div>}
