function BudgetModal({budget,baseCurrency,onSubmit,onClose,busy}:{budget:Budget;baseCurrency:string;onSubmit:(e:FormEvent<HTMLFormElement>)=>void;onClose:()=>void;busy:boolean}){return <div className="modal-backdrop"><form className="modal" onSubmit={onSubmit}><span className="section-kicker">快速调整</span><h2>{categoryLabel(budget.category)}预算</h2><p>修改本月预算金额，支出进度会立即重新计算。</p><label>预算金额（{baseCurrency}）<input name="amount" type="number" min="1" step="100" defaultValue={budget.amount} required autoFocus/></label><div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button className="primary" disabled={busy}>保存预算</button></div></form></div>}
function TransactionModal({transaction,categories,tags,baseCurrency,selectedTagIds,onSubmit,onSaveRate,onRestoreAuto,onClose,busy}:{transaction:Tx;categories:Category[];tags:Tag[];baseCurrency:string;selectedTagIds:string[];onSubmit:(e:FormEvent<HTMLFormElement>)=>void;onSaveRate:(transaction:Tx,value:string)=>Promise<boolean>;onRestoreAuto:(transaction:Tx)=>Promise<void>;onClose:()=>void;busy:boolean}){
 const initial=(transaction.transaction_type??(transaction.raw_data?.kind==="credit_card_repayment"?"transfer":transaction.raw_data?.kind==="cash_withdrawal"?"cash":transaction.raw_data?.kind??transaction.direction)) as TransactionType;
 const[type,setType]=useState<TransactionType>(initial),[categoryId,setCategoryId]=useState(transaction.category_id??""),[editingRate,setEditingRate]=useState(false),[rateInput,setRateInput]=useState(transaction.exchange_rate?String(transaction.exchange_rate):"");
 const originalCurrency=transaction.original_currency??transaction.raw_data?.currency??"CNY",originalAmount=Number(transaction.original_amount??transaction.amount),candidate=parseManualRate(rateInput),preview=candidate===null?null:originalAmount*candidate,isForeign=originalCurrency!==baseCurrency,roots=categories.filter(c=>!c.parent_id&&c.type===type),subs=categories.filter(c=>c.parent_id===categoryId),source=transaction.exchange_rate_source==="manual"?"手动设置":transaction.exchange_rate_source?`自动 · ${transaction.exchange_rate_source}`:"待获取";
 return <div className="modal-backdrop"><form className="modal transaction-modal" onSubmit={onSubmit}><span className="section-kicker">交易审核</span><h2>编辑交易</h2><div className="readonly-grid"><div><span>交易日期</span><strong>{transaction.transaction_date}</strong></div><div><span>原始金额</span><strong>{money(originalAmount,originalCurrency)}</strong></div><div><span>币种</span><strong>{originalCurrency}</strong></div></div><label>描述 / 商户<input name="description" defaultValue={displayDescription(transaction)} required/></label><div className="raw-description"><span>银行原始描述</span><p>{transaction.raw_data?.original_description??transaction.description}</p></div><label>备注<textarea name="note" defaultValue={transaction.note??""} maxLength={1000} rows={4} placeholder="例如：和朋友吃生日饭"/></label>
 {isForeign&&<section className="fx-card"><h3>汇率与折算</h3><div className="fx-facts"><span>原始金额<strong>{money(originalAmount,originalCurrency)}</strong></span><span>当前汇率<strong>{transaction.exchange_rate?`1 ${originalCurrency} = ${transaction.exchange_rate} ${baseCurrency}`:"待获取"}</strong></span><span>折算金额<strong>{transaction.base_amount!==null?money(Number(transaction.base_amount),baseCurrency):"—"}</strong></span><span>汇率日期<strong>{transaction.exchange_rate_source==="manual"?"不适用":transaction.exchange_rate_date??"—"}</strong></span><span>汇率来源<strong>{source}</strong></span></div>{editingRate?<div className="fx-override"><label>1 {originalCurrency} = <input value={rateInput} onChange={event=>setRateInput(event.target.value)} inputMode="decimal" placeholder="输入汇率"/> {baseCurrency}</label>{preview!==null?<div className="fx-preview"><span>{money(originalAmount,originalCurrency)}</span><b>× {candidate}</b><strong>= {money(preview,baseCurrency)}</strong></div>:<small className="pending-rate">请输入大于 0 的有效数字。</small>}<div className="fx-actions"><button type="button" onClick={()=>{setRateInput(transaction.exchange_rate?String(transaction.exchange_rate):"");setEditingRate(false)}}>取消</button><button type="button" className="primary small" disabled={busy||candidate===null} onClick={async()=>{if(await onSaveRate(transaction,rateInput))setEditingRate(false)}}>保存汇率</button></div></div>:<div className="fx-actions"><button type="button" className="edit-button" onClick={()=>setEditingRate(true)}>{transaction.conversion_status==="pending"?"手动输入汇率":"修改汇率"}</button>{transaction.conversion_status==="pending"&&<button type="button" className="edit-button" disabled={busy} onClick={()=>void onRestoreAuto(transaction)}>重新获取汇率</button>}{transaction.exchange_rate_source==="manual"&&<button type="button" className="text-button" disabled={busy} onClick={()=>void onRestoreAuto(transaction)}>恢复自动汇率</button>}</div>}</section>}
 <label>交易类型<select name="transaction_type" value={type} onChange={e=>{const next=e.target.value as TransactionType;setType(next);setCategoryId("")}}>{Object.entries(transactionTypeLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><div className="form-row"><label>分类<select name="category_id" disabled={type==="review"} value={categoryId} onChange={e=>setCategoryId(e.target.value)}><option value="">请选择</option>{roots.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>子分类<select name="subcategory_id" disabled={type==="review"||!categoryId} defaultValue={transaction.subcategory_id??""}><option value="">未分类</option>{subs.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label></div><fieldset className="tag-picker"><legend>标签（可多选）</legend>{tags.length?tags.map(tag=><label key={tag.id}><input type="checkbox" name="tags" value={tag.id} defaultChecked={selectedTagIds.includes(tag.id)}/><span>#{tag.name}</span></label>):<p>可从页面顶部“管理标签”创建。</p>}</fieldset><label>状态<select name="status" defaultValue={transaction.status}><option value="review">待确认</option><option value="confirmed">已确认</option></select></label><div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button className="primary" disabled={busy}>保存交易</button></div></form></div>
}
function SettingsModal({baseCurrency,busy,onSave,onClose}:{baseCurrency:string;busy:boolean;onSave:(currency:string)=>void;onClose:()=>void}){const[value,setValue]=useState(baseCurrency);return <div className="modal-backdrop"><div className="modal"><span className="section-kicker">财务设置</span><h2>本位币</h2><p>Dashboard、预算和图表会将已折算交易统一换算为本位币。更换后，其他币种需要重新确认历史汇率。</p><label>本位币<select value={value} onChange={event=>setValue(event.target.value)}>{["CNY","HKD","USD","EUR","JPY","AUD","SGD"].map(currency=><option key={currency}>{currency}</option>)}</select></label><div className="modal-actions"><button onClick={onClose}>取消</button><button className="primary" disabled={busy} onClick={()=>onSave(value)}>保存设置</button></div></div></div>}
function TagManager({tags,onCreate,onRename,onDelete,onClose}:{tags:Tag[];onCreate:(name:string)=>void;onRename:(tag:Tag,name:string)=>void;onDelete:(tag:Tag)=>void;onClose:()=>void}){const[name,setName]=useState("");return <div className="modal-backdrop"><div className="modal"><span className="section-kicker">交易情境</span><h2>标签管理</h2><form className="tag-create" onSubmit={e=>{e.preventDefault();void onCreate(name);setName("")}}><input value={name} onChange={e=>setName(e.target.value)} placeholder="例如：日本旅行 2026" maxLength={60}/><button className="primary small" disabled={!name.trim()}>创建</button></form><div className="tag-manager-list">{tags.map(tag=><div key={tag.id}><span>#{tag.name}</span><button onClick={()=>{const next=window.prompt("新的标签名称",tag.name);if(next)void onRename(tag,next)}}>重命名</button><button className="danger-text" onClick={()=>void onDelete(tag)}>删除</button></div>)}{!tags.length&&<p className="panel-subtitle">还没有标签。</p>}</div><div className="modal-actions"><button type="button" onClick={onClose}>完成</button></div></div></div>}
function Accounts({accounts,transactions,onAdd,onEdit,onRestore}:{accounts:Account[];transactions:Tx[];onAdd:()=>void;onEdit:(account:Account)=>void;onRestore:(account:Account)=>void}){const balances=accountCurrencyBalances(transactions);return <section className="panel"><div className="panel-heading"><h2>我的账户</h2><button className="primary small" onClick={onAdd}><Plus/>新增账户</button></div>{accounts.length?<div className="account-list">{accounts.map(account=><div className={`account ${account.is_archived?"archived":""}`} key={account.id}><Landmark/><div><b>{account.name}</b><span>{account.institution||"未填写银行"}{account.is_archived?" · 已归档":""}</span><span className="currency-positions">{balances.get(account.id)?.size?[...balances.get(account.id)!].map(([currency,value])=><em key={currency}>{money(value,currency)}</em>):<em>{money(0,account.currency??"CNY")}</em>}</span></div>{account.is_archived?<button className="edit-button" onClick={()=>onRestore(account)}>恢复</button>:<button className="edit-button" onClick={()=>onEdit(account)}><Pencil/>编辑</button>}</div>)}</div>:<div className="empty">还没有账户。</div>}</section>}
function Statements({statements,deleting,onDelete}:{statements:Statement[];deleting:string;onDelete:(statement:Statement)=>void}){return <section className="panel"><h2>已上传账单</h2>{statements.length?<div className="statement-list">{statements.map(s=><div className="statement" key={s.id}><FileText/><div><b>{s.file_name}</b><span>{s.period_start&&s.period_end?`${s.period_start} 至 ${s.period_end}`:"账期识别中"}</span></div><span className="status ok">{s.status==="parsed"?"已解析":s.status}</span><button className="delete-statement" disabled={deleting===s.id} onClick={()=>onDelete(s)}>{deleting===s.id?<LoaderCircle className="spin"/>:<Trash2/>}<span>{deleting===s.id?"删除中":"删除"}</span></button></div>)}</div>:<div className="empty">还没有上传账单。</div>}</section>}
